const LIST_KEYS = ['jobs', 'results', 'data', 'items', 'posts'];
const raw = $input.all().map(i => i.json);
const list = [];
for (const r of raw) {
  if (Array.isArray(r)) list.push(...r);
  else if (r && typeof r === 'object') {
    const k = LIST_KEYS.find(k => Array.isArray(r[k]));
    if (k) list.push(...r[k]);
    else list.push(r);
  } else if (r !== null && r !== undefined) list.push(r);
}

const pick = (...v) => v.find(x => x !== undefined && x !== null && x !== '') || '';
const hash = s => {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  return (h >>> 0).toString(16).padStart(8, '0');
};

// ponytail: this node is re-invoked once per input branch, because n8n
// re-triggers everything downstream of a multi-input Merge. Per-invocation
// state therefore handed every source its own LLM_BUDGET (32 jobs reached
// the LLM instead of 8) and let cross-source duplicates through, since the
// dedupe sets were rebuilt from scratch on every branch.
// $getWorkflowStaticData is the only state that survives between
// invocations of the same execution; the execId check throws it away at the
// start of the next run so a stale run cannot poison the next one.
const store = $getWorkflowStaticData('global');
if (store.execId !== $execution.id) {
  store.execId = $execution.id;
  store.urls = Object.create(null);
  store.keys = Object.create(null);
  store.emitted = 0;
}
const seenUrls = new Set(Object.keys(store.urls));
const seenKeys = new Set(Object.keys(store.keys));
const out = [];
for (const job of list) {
  if (!job || typeof job !== 'object') continue;
  const company  = pick(job.company_name, job.companyName, job.company, job.author);
  const title    = pick(job.title, job.jobTitle, job.job_title, job.position);
  const location = pick(job.city, job.location, job.jobGeo, job.candidate_required_location,
                     Array.isArray(job.locationRestrictions) ? job.locationRestrictions.join(', ') : '');
  if (!company && !title) continue;
  const url    = pick(job.url, job.job_url, job.apply_url, job.applicationLink, job.guid);
  // ponytail: cap the JD. RemoteOK sends multi-KB HTML blobs and ollama runs
  // at ~14 tok/s prompt eval on CPU, so an uncapped JD turns a 5 min run into
  // an hour. 1800 chars is plenty of signal for skills + responsibilities.
  const rawJd  = pick(job.description, job.jobDescription, job.body, job.job_description);
  const jd     = String(rawJd || '').replace(/<[^>]*>/g, ' ')
                      .replace(/\s+/g, ' ').trim().slice(0, 1800);
  // remotive/remoteok/himalayas/arbeitnow have no source field, so every row
  // used to land as "scraped"; derive it from the posting host instead.
  const source = job.source || job.site
    || (String(url).match(/^https?:\/\/([^/]+)/)?.[1] || '').replace(/^www\./, '')
    || 'scraped';
  const posted = (() => {
    const v = pick(job.date_posted, job.publication_date, job.pubDate,
                   job.publishedAt, job.date, job.created_at);
    if (v === '') return '';
    if (typeof v === 'number' || /^\d{9,13}$/.test(String(v))) {
      const d = new Date(String(v).length > 10 ? Number(v) : Number(v) * 1000);
      return isNaN(d.getTime()) ? '' : d.toISOString().slice(0, 10);
    }
    return String(v).slice(0, 10);
  })();

  const normUrl = String(url).trim().toLowerCase().replace(/\/+$/, '');
  if (normUrl && seenUrls.has(normUrl)) continue;
  if (normUrl) { seenUrls.add(normUrl); store.urls[normUrl] = 1; }
  const key = `${company.toLowerCase().trim()}|${title.toLowerCase().trim()}|${location.toLowerCase().trim()}`;
  if (seenKeys.has(key)) continue;
  seenKeys.add(key); store.keys[key] = 1;

  out.push({
    job_id: hash(normUrl || key),
    company, title, location,
    company_url: pick(job.company_url, job.employer_url),
    experience: '',
    job_url: url,
    jd: String(jd).slice(0, 4000),
    source,
    posted_date: posted,
    discovered_date: new Date().toISOString()
  });
}

// ponytail: LLM is 60s/call on CPU, so prefilter + cap before spending LLM time.
// Word boundaries matter: the bare word SWIFT matches the SWIFT payments
// network in banking ads, which is how a Fireblocks sales job passed a filter
// looking for Swift/iOS developers. NEG drops whole non-tech categories that
// these boards are full of (a psychologist, a sales engineer, a content
// creator all reached the LLM in real runs).
const NEG = /(psycholog|therap|sales engineer|account (manager|director)|recruit|marketing|customer success|graphic design|content creator|teacher|professor|nurse|legal counsel|accountant)/i;
const MOBILE = /(\bflutter\b|\bandroid\b|\bios\b|\biphone\b|\bswift\b|\bkotlin\b|mobile app|react native|\bdart\b|jetpack|\bmvvm\b|\bmvp\b|firebase|app development|app store|google play|android studio|\bxcode\b)/i;
const STRONG = /(\bflutter\b|\bandroid\b|\bios\b|\biphone\b|\bswift\b|\bkotlin\b|react native|mobile app)/i;
// 3 = the title itself says mobile. Measured over 546 live postings: 3 mobile
// titles in the API sources against 7/7 from naukri, so a slot spent on a
// board that never returns a mobile role is a slot wasted.
for (const j of out) {
  const t = j.title || '';
  j._rel = NEG.test(t) ? 0 : (STRONG.test(t) ? 3 : (MOBILE.test(t + ' ' + j.jd) ? 1 : 0));
}
const relevant = out.filter(j => j._rel > 0).sort((a, b) => b._rel - a._rel);
// ponytail: 8, not 12. ollama runs ~127s per job on a capped prompt
  // (~550 token prompt at 14 tok/s eval + 500 max_tokens at 5.75 tok/s gen),
  // so 12 would take ~25-38 min and overrun the 30-min cron.
const LLM_BUDGET = 8;
// Whatever earlier branches already spent. The first branch to deliver
// relevant jobs takes the budget, which is the intended outcome now that the
// three measured-dead boards are gone and naukri (7/7 mobile) is first.
const remaining = Math.max(0, LLM_BUDGET - (store.emitted || 0));
if (!remaining) return [];
const ranked = relevant.length ? relevant : out;
// Round-robin the budget across hosts, but only across hosts that have
// actually produced a mobile-titled job. Round-robin over every host spent
// 3 of 8 slots on EU boards yielding 0.31% mobile roles; restricting it to
// strong-title hosts took a run from 5/8 to 8/8 mobile jobs.
const strongHosts = new Set(out.filter(j => j._rel >= 3).map(j => j.source));
const byHost = new Map();
for (const j of ranked) {
  // a host with no strong job is only used once every strong host is spent
  const key = strongHosts.has(j.source) ? j.source : '~' + j.source;
  if (!byHost.has(key)) byHost.set(key, []);
  byHost.get(key).push(j);
}
const strongList = [...byHost.entries()].filter(([k]) => !k.startsWith('~')).map(([, v]) => v);
const weakList = [...byHost.entries()].filter(([k]) => k.startsWith('~')).flatMap(([, v]) => v);
const byHostOrdered = [...new Map([...strongList, ...weakList].map((v) => [v[0], v])).values()];
const keep = [];
for (let i = 0; keep.length < remaining; i++) {
  let added = false;
  for (const list of byHostOrdered) {
    if (i < list.length) { keep.push(list[i]); added = true; }
    if (keep.length >= remaining) break;
  }
  if (!added) break;
}
for (const j of keep) delete j._rel;
store.emitted = (store.emitted || 0) + keep.length;
return keep;

