// The LLM node is an httpRequest, so its output replaces the input item and all
// job fields are gone. The HTTP Request node runs items in order, so zip back
// against the Normalize node's output by index to recover company/title/url.
const src = $('Normalize + Dedupe').all();
const results = [];

$input.all().forEach((it, i) => {
  const j = it.json || {};
  const base = (src[i] && src[i].json) || {};
  let raw = (j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content) || '{}';
  raw = String(raw).trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  let a = {};
  try { a = JSON.parse(raw); } catch (e) { a = {}; }

  // Deterministic experience gate. A job ad states the minimum the employer
  // will ACCEPT, not a bar the candidate has to clear, so decide on the LOW
  // number of the range: "0-3 years" accepts a 3-year candidate. The 7b model
  // was reading the same rule inverted and discarding 4 of 100 real jobs.
  // `experience` is empty on every real posting, so parse the JD text.
  const blob = String(base.jd || '').slice(0, 2000);
  const ym = blob.match(/(\d{1,2})\s*(?:-|to|\u2013|\u2014)\s*(\d{1,2})\s*(?:years?|yrs?)|\b(\d{1,2})\s*\+?\s*(?:years?|yrs?)\b/i);
  let gate;
  if (ym) {
    const lo = parseInt(ym[1] || ym[3], 10);
    gate = lo > 4 ? 'REJECT' : (lo > 3 ? 'REVIEW' : 'PASS');
  } else {
    // No stated experience is not a disqualifier - 92% of real postings say
    // nothing. A senior/lead title is not evidence either; the candidate is
    // himself a Lead Mobile App Developer.
    gate = 'MISSING_DATA';
  }
  if (gate === 'REJECT') { a.overall_score = -1; }

  const num = (v) => Math.max(0, Math.min(100, Number(v) || 0));
  const role = num(a.role_match), skill = num(a.skill_match), loc = num(a.location_match);
  // `recommended` had no rule at all, so the model guessed (a job scoring 85
  // came back false). Location counts: a posting in France is not actionable
  // for a candidate based in Pune.
  const recommended = gate !== 'REJECT' && role >= 50 && skill >= 60 && loc >= 30;

  results.push({
    job_id: base.job_id || '',
    company: base.company || '',
    source: base.source || '',
    jd: base.jd || '',
    posted_date: base.posted_date || '',
    discovered_date: base.discovered_date || new Date().toISOString(),
    last_updated: new Date().toISOString(),
    title: base.title || '',
    location: base.location || '',
    company_url: base.company_url || '',
    job_url: base.job_url || '',
    experience: '',
    experience_status: gate,
    experience_reason: a.experience_reason || '',
    role_match: a.role_match || 0,
    skill_match: a.skill_match || 0,
    location_match: a.location_match ?? 50,
    tweak_level: a.tweak_level || 50,
    overall_score: a.overall_score || 0,
    recommended: recommended,
    why_this_job: a.why_this_job || '',
    matched_skills: a.matched_skills || [],
    missing_skills: a.missing_skills || [],
    review_required: gate === 'REVIEW'
  });
});

const pass = results.filter(r => r.experience_status === 'PASS');
const other = results.filter(r => r.experience_status !== 'PASS');
pass.sort((a, b) =>
  ((b.overall_score || 0) - (a.overall_score || 0))
  || ((a.tweak_level || 0) - (b.tweak_level || 0))
  || ((b.skill_match || 0) - (a.skill_match || 0))
);
return pass.concat(other).slice(0, 100);

// Report only jobs the sheet had never seen AND that clear the skill bar.
// sheet_action comes from the scraper's /sheets/upsert response, so 'appended'
// means brand new to us; the skill bar is what stops Score -1 / Skills 0% rows
// (Regional Sales Manager, Designer...) from reaching Telegram.
// Returning zero items makes n8n skip the Telegram node entirely.
//
// min_skill_match comes from the Get Settings branch (dashboard Settings page,
// stored in /opt/jbfind/data/settings.json). Any failure - node missing,
// scraper down, junk value - degrades to the default instead of killing the run.
let MIN_SKILL_MATCH = 60;
try {
  const v = Number($('Get Settings').first().json.min_skill_match);
  if (Number.isFinite(v)) MIN_SKILL_MATCH = v;
} catch (e) { /* keep the default */ }

const out = [];
for (const item of items) {
  const data = item.json.data || [];
  const fresh = data
    .filter((j) => j.sheet_action === "appended"
      && Number(j.skill_match || 0) >= MIN_SKILL_MATCH)
    .sort((a, b) => Number(b.overall_score || 0) - Number(a.overall_score || 0));
  if (fresh.length) out.push({ json: { ...item.json, data: fresh } });
}
return out;

// One Telegram card per job: explode the report array into items.
const out = [];
for (const item of $input.all()) {
  for (const j of (item.json.data || []).slice(0, 10)) out.push({ json: j });
}
return out;

const prev = $getWorkflowStaticData('global');
const key = String($json.execution.error.message || 'err').slice(0,120);
const now = Date.now();
const last = prev.lastAlert || {};
if (last.key === key && now - last.at < 30*60*1000) {
  return [];
}
prev.lastAlert = { key, at: now };
return items;
